package android.graphics; import java.awt.*;import java.awt.font.*;public class Paint {public Color color=Color.WHITE;public float size=20,stroke=1;public static Font font;public int breakText(String s,boolean forward,float max,float[] measured){int n=s.length();while(n>0&&measureText(s.substring(0,n))>max)n--;return n;}public void setColor(int c){color=new Color(c,true);}public void setTextSize(float s){size=s;}public float measureText(String s){return (float)font.deriveFont(size).getStringBounds(s,new FontRenderContext(null,false,false)).getWidth();}public void setStrokeWidth(float s){stroke=s;}public void setAntiAlias(boolean b){}public void setFilterBitmap(boolean b){}}